scwin.trigger1_onclick = function(e) {
    /*
     * gotoTime( hour, min )	//특정 시간으로 이동
     * gotoToday()	//달력의 today버튼 누르는 것과 동일
     * gotoCalendar( dateStr )	//특정일로 이동
     * gotoMonth( month )	//특정월로 이동
     * gotoLastMonth()	//선택된 날짜 기준 한달 전으로 이동
     * gotoNextMonth()	//선택된 날짜 기준 한달 후로 이동
     * gotoYear( year )	//특정년도로 이동
     * gotoLastYear()	//선택된 날짜 기준 1년 전으로 이동
     * gotoNextYear()	//선택된 날짜 기준 1년 후로 이동
     */
    calendar1.gotoLastMonth();
    //inputCalendar1.goto
};
