scwin.checkVal = function() {
    var calendar_str = WebSquare.wUnit.getDomById($p.id + 'inputCalendar3_input').value;
    return calendar_str.indexOf('01:02:03') > 0;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_hour').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_hour_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_minute').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_minute_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_second').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_calendar_selectbox_second_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_time_confirm')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inputCalendar3_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /*
     * calendar는 특정 '시간, 날짜, 월, 년'에 해당하는 날짜로 이동할 수 있다.
     */
    /*
     * inputCaelndar의 사용자입력이 끝난 후 blur보다 이전에 발생됨.
     * dateValidCheck, validCheck 속성과는 무관한 듯 보임.
     * 
     */
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
